CREATE OR REPLACE FUNCTION public.release_bundle_source(_register text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE src jsonb; rev jsonb:='[]'; n int; v int; fp text; blocked boolean; source_table text; review_table text;
BEGIN
 SELECT CASE _register WHEN 'release_readiness' THEN 'release_signoffs' WHEN 'release_evidence' THEN 'release_evidence' WHEN 'publish_gate' THEN 'release_review_acks' WHEN 'release_runbook' THEN 'release_drill_runs' WHEN 'backup_evidence' THEN 'backup_evidence' WHEN 'protection_evidence' THEN 'protection_evidence' WHEN 'content_review' THEN 'content_review' WHEN 'access_matrix' THEN 'access_audit' WHEN 'verification_campaign' THEN 'campaign_results' WHEN 'campaign_history' THEN 'campaign_runs' WHEN 'production_readiness' THEN 'test_prerequisites' WHEN 'owner_action_queue' THEN 'owner_action_items' WHEN 'golive_decision_pack' THEN 'decision_signoffs' WHEN 'test_session_workspace' THEN 'test_sessions' WHEN 'human_review_console' THEN 'review_rounds' WHEN 'content_approval' THEN 'content_approval' WHEN 'launch_control' THEN 'launch_control_item' WHEN 'integration_safety' THEN 'integration_safety_item' WHEN 'incident_console' THEN 'incident_console_item' WHEN 'evidence_inspector' THEN 'evidence_inspector_item' END INTO source_table;
 IF source_table IS NULL THEN RAISE EXCEPTION 'INVALID_ARGUMENTS'; END IF;
 SELECT CASE _register WHEN 'release_readiness' THEN 'release_approvals' WHEN 'backup_evidence' THEN 'backup_evidence_confirmations' WHEN 'protection_evidence' THEN 'protection_evidence_confirmations' WHEN 'content_review' THEN 'content_review_acks' WHEN 'access_matrix' THEN 'access_audit_confirmations' WHEN 'verification_campaign' THEN 'campaign_result_confirmations' WHEN 'production_readiness' THEN 'test_prerequisite_reviews' WHEN 'owner_action_queue' THEN 'owner_action_reviews' WHEN 'test_session_workspace' THEN 'test_session_reviews' WHEN 'human_review_console' THEN 'review_decisions' WHEN 'content_approval' THEN 'content_approval_reviews' WHEN 'launch_control' THEN 'launch_control_review' WHEN 'integration_safety' THEN 'integration_safety_review' WHEN 'incident_console' THEN 'incident_console_review' WHEN 'evidence_inspector' THEN 'evidence_inspector_review' END INTO review_table;
 -- Allowlisted readiness tables only. Free-form content is never projected or fingerprinted.
 EXECUTE format('SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''v'',coalesce(to_jsonb(t)->>''version'',to_jsonb(t)->>''round'',to_jsonb(t)->>''run_no'',''1''),''lineage'',coalesce(to_jsonb(t)->>''lineage'',to_jsonb(t)->>''item_key'',to_jsonb(t)->>''suite_key'',to_jsonb(t)->>''key'',to_jsonb(t)->>''check_id'',''all''),''status'',coalesce(to_jsonb(t)->>''status'',to_jsonb(t)->>''observed_status'',to_jsonb(t)->>''outcome'',''unverified''),''at'',created_at) ORDER BY id),''[]'') FROM public.%I t',source_table) INTO src;
 IF review_table IS NOT NULL THEN EXECUTE format('SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''status'',coalesce(to_jsonb(t)->>''outcome'',to_jsonb(t)->>''decision'',''unverified''),''at'',created_at) ORDER BY id),''[]'') FROM public.%I t',review_table) INTO rev; END IF;
 -- Canonical, unambiguous SHA-256 structural fingerprint, truncated to the existing 128-bit format.
 fp:=substr(encode(sha256(convert_to(jsonb_build_object('sources',src,'reviews',rev)::text,'UTF8')),'hex'),1,32);
 SELECT count(*),coalesce(max((x->>'v')::int),0),coalesce(bool_or(x->>'status' IN ('blocked','failed','concern','rejected','approved','rollback_recommended','open')),false) INTO n,v,blocked FROM (SELECT DISTINCT ON (x->>'lineage') x FROM jsonb_array_elements(src) x ORDER BY x->>'lineage',(x->>'v')::int DESC,x->>'at' DESC) latest;
 blocked:=blocked OR EXISTS(SELECT 1 FROM jsonb_array_elements(rev) x WHERE x->>'status' IN ('concern','rejected'));
 RETURN jsonb_build_object('register',_register,'fingerprint',fp,'source_count',n,'source_version',v,'status',CASE WHEN blocked THEN 'blocked' WHEN n>0 AND EXISTS(SELECT 1 FROM jsonb_array_elements(src) x WHERE x->>'status'='pending') THEN 'pending' ELSE 'unverified' END,'reason',CASE WHEN n=0 THEN 'Missing artifact' WHEN blocked THEN 'Source evidence blocked' ELSE 'Source readiness unverified' END);
END $$;
REVOKE ALL ON FUNCTION public.release_bundle_source(text) FROM PUBLIC,anon,authenticated;